function onSubmit() {

   //Type appropriate comment here, and begin script below
	// var startDateStr = g_form.getValue('start_date');
	// var endDateStr = g_form.getValue('end_date');

	// var startDate = getDateFromFormat(startDateStr, g_user_date_format);
	// var endDate = getDateFromFormat(endDateStr, g_user_date_format);

	// var diffInMs = endDate - startDate;
    // var days = diffInMs / (1000 * 60 * 60 * 24);

	var leaveDays = g_form.getValue('number_of_leave_days');
	var leaveType = g_form.getValue('leave_type');

	if((leaveDays>2)&&(leaveType=='sick_leave')) {

		// alert(leaveDays+"::"+leaveType);

		var attachmentBanner = document.getElementById('header_attachment_list_label');

		if (!attachmentBanner || attachmentBanner.getElementsByTagName('li').length === 0) {
            // Block submission and alert the user
            g_form.addErrorMessage('A medical certificate must be attached via the paperclip icon for sick leave exceeding 2 days.');
            return false; 
        }
	}

}
